mapper.select:
SELECT bcode, "idNumber", title, content, "createdAt"
FROM public.board
WHERE bcode = #{bcode}

mapper.update:
UPDATE public.board
SET
	title = #{title}, content = #{content}
WHERE
	bcode = #{bcode} AND "idNumber" = #{idNumber}

mapper.delete:
DELETE FROM public.board
WHERE bcode = #{bcode}
AND "idNumber" = #{idNumber}
